406		if _, err := tx.ExecContext(ctx, `DELETE FROM memo_share WHERE creator_id = `+deleteUserPlaceholder(1), userID); err != nil {
407			return err
408		}
409		for _, batch := range deleteUserBatches(memoIDs, deleteUserBatchSize) {
410			clause, args := deleteUserInClause(1, batch)
411			if _, err := tx.ExecContext(ctx, `DELETE FROM memo_share WHERE memo_id IN `+clause, args...); err != nil {
412				return err
413			}
414		}
415		return nil
416	}
417	
418	func deleteInboxesByIDsTx(ctx context.Context, tx *sql.Tx, inboxIDs []int32) error {
419		for _, batch := range deleteUserBatches(inboxIDs, deleteUserBatchSize) {
420			clause, args := deleteUserInClause(1, batch)
421			if _, err := tx.ExecContext(ctx, `DELETE FROM inbox WHERE id IN `+clause, args...); err != nil {
422				return err
423			}
424		}
425		return nil
426	}
427	
428	func deleteUserIdentitiesTx(ctx context.Context, tx *sql.Tx, userID int32) error {
429		_, err := tx.ExecContext(ctx, `DELETE FROM user_identity WHERE user_id = `+deleteUserPlaceholder(1), userID)
430		return err
