466	func deleteUserPlaceholder(_ int) string {
467		return "?"
468	}
469	
470	func deleteUserInClause[T any](start int, values []T) (string, []any) {
471		placeholders := make([]string, 0, len(values))
472		args := make([]any, 0, len(values))
473		for i, value := range values {
474			placeholders = append(placeholders, deleteUserPlaceholder(start+i))
475			args = append(args, value)
476		}
477		return "(" + strings.Join(placeholders, ", ") + ")", args
478	}
479	
480	func deleteUserBatches[T any](values []T, size int) [][]T {
481		if len(values) == 0 {
482			return nil
483		}
484		if size <= 0 {
485			size = len(values)
486		}
487	
488		batches := make([][]T, 0, (len(values)+size-1)/size)
489		for start := 0; start < len(values); start += size {
490			end := min(start+size, len(values))
491			batches = append(batches, values[start:end])
492		}
493		return batches
494	}
495	
496	func memoIDsFromRefs(memos []deleteUserMemoRef) []int32 {
497		ids := make([]int32, 0, len(memos))
498		for _, memo := range memos {
499			ids = append(ids, memo.ID)
500		}
501		return ids
502	}
503	
504	func memoIDSetFromRefs(memos []deleteUserMemoRef) map[int32]struct{} {
505		idSet := make(map[int32]struct{}, len(memos))
506		for _, memo := range memos {
507			idSet[memo.ID] = struct{}{}
508		}
509		return idSet
510	}
511	
512	func memoContentIDsFromRefs(memos []deleteUserMemoRef) []string {
513		contentIDs := make([]string, 0, len(memos))
514		for _, memo := range memos {
515			contentIDs = append(contentIDs, "memos/"+memo.UID)
516		}
517		return contentIDs
518	}
519	
520	func attachmentIDsFromList(attachments []*store.Attachment) []int32 {
521		ids := make([]int32, 0, len(attachments))
522		for _, attachment := range attachments {
523			if attachment == nil {
524				continue
525			}
526			ids = append(ids, attachment.ID)
527		}
528		return ids
529	}
